import React, { useState } from 'react'; // eslint-disable-line no-unused-vars
import { useNavigate } from 'react-router-dom';
import { makeStyles } from '@mui/styles';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableRow from '@mui/material/TableRow';
import Skeleton from '@mui/material/Skeleton';
import Typography from '@mui/material/Typography';
import Avatar from '@mui/material/Avatar';
import Chip from '@mui/material/Chip';
import SportsSoccerIcon from '@mui/icons-material/SportsSoccer';
import EventIcon from '@mui/icons-material/Event';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';
import KeyboardArrowUpIcon from '@mui/icons-material/KeyboardArrowUp';
import IconButton from '@mui/material/IconButton';
import { allRoles, allCountries, allSeasons } from '../utils/generals';
import Flag from './Flag';

const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
    height: '100%',
    display: 'flex',
    flexDirection: 'column',
  },
  content: {
    flex: 1,
    overflowY: 'auto',
    padding: theme.spacing(0, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  sectionLabel: {
    fontSize: '0.65rem',
    fontWeight: 800,
    letterSpacing: '0.08em',
    textTransform: 'uppercase',
    color: theme.palette.primary.main,
    padding: theme.spacing(1, 1, 0.25),
  },
  header: {
    fontSize: '0.78rem',
    fontWeight: 700,
    color: '#082D68',
    padding: '8px 8px',
  },
  row: {
    cursor: 'pointer',
    '&:hover': {
      backgroundColor: theme.palette.action.hover,
    },
  },
  cell: {
    padding: '8px 8px',
    fontSize: '0.82rem',
  },
  avatar: {
    width: 26,
    height: 26,
    fontSize: '0.65rem',
    fontWeight: 700,
    backgroundColor: '#CA2331',
    color: '#fff',
  },
  avatarBlue: {
    width: 26,
    height: 26,
    fontSize: '0.65rem',
    fontWeight: 700,
    backgroundColor: '#082D68',
    color: '#fff',
  },
  breakdownRow: {
    backgroundColor: 'rgba(8,45,104,0.025)',
  },
  breakdownCell: {
    padding: '4px 8px',
    fontSize: '0.72rem',
    borderBottom: 'none',
    color: 'rgba(0,0,0,0.7)',
  },
  breakdownLabel: {
    padding: '4px 8px 4px 42px',
    fontSize: '0.72rem',
    borderBottom: 'none',
    fontWeight: 600,
    color: 'rgba(0,0,0,0.6)',
  },
  breakdownTotalRow: {
    backgroundColor: 'rgba(8,45,104,0.06)',
  },
  yellowShape: {
    backgroundColor: '#FDDB3A',
    width: 14,
    height: 20,
  },
  redShape: {
    backgroundColor: '#CA2331',
    width: 14,
    height: 20,
  },
}));

const LEAGUE_INFO = {
  'A':   { name: 'Serie A',       slug: 'serie-A',   color: '#082D68' },
  'B':   { name: 'Serie B',       slug: 'serie-B',   color: '#CA2331' },
  'C1':  { name: 'Serie C1',      slug: 'serie-C1',  color: '#E87722' },
  '1RS': { name: 'Prima Div.',    slug: 'serie-1RS', color: '#6A0DAD' },
};

export default function Players({ players, coaches = [], seasonID, seasonLabel, onPlayerSelect }) {
  const classes = useStyles();
  const navigate = useNavigate();
  const [expanded, setExpanded] = useState(() => new Set());
  if (typeof players === 'undefined') players = [];

  const currentSeason = allSeasons.find(s => String(s.id) === String(seasonID));
  const leagueInfo = currentSeason ? LEAGUE_INFO[currentSeason.league] : null;
  const leagueLabel = leagueInfo ? leagueInfo.name : 'Campionato';

  // I valori arrivano dall'API come stringhe: normalizzo prima di sommare.
  const num = (v) => {
    const n = parseInt(v, 10);
    return isNaN(n) ? 0 : n;
  };

  // `ci` è null quando per quella stagione non esistono dati di Coppa Italia:
  // in quel caso non mostro il toggle, così "nessun dato" resta distinto da "zero".
  const hasCup = (row) => row.ci !== null && typeof row.ci !== 'undefined';

  const toggleExpanded = (id) => {
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };

  const getFlag = (flag) => {
    const country = allCountries.filter(c => c.description.toLowerCase() === flag.toLowerCase());
    return country[0]?.flag;
  };

  if (players.length > 0) {
    players.map((player) => player.roleabbrevation = allRoles.filter((role) => role.description === player.role));
  }

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={<Chip label={seasonLabel || 'Rosa'} size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />}
        title="Rosa"
        subheader="Cagliari Calcio"
        action={leagueInfo && (
          <Chip
            label={leagueInfo.name}
            size="small"
            onClick={() => navigate(`/cagliari-calcio/stagioni/${leagueInfo.slug}`)}
            style={{ fontWeight: 700, backgroundColor: leagueInfo.color, color: '#fff', cursor: 'pointer', margin: '12px 8px 0 0' }}
          />
        )}
      />
      <CardContent className={classes.content}>
        <TableContainer>
          <Table size="small" aria-label="rosa stagione">
            <TableBody>
              {coaches.length > 0 && (
                <>
                  <TableRow style={{ backgroundColor: '#fafafa' }}>
                    <TableCell className={classes.header}>Allenatore</TableCell>
                    <TableCell className={classes.header} colSpan={7} />
                  </TableRow>
                  {coaches.map((coach) => (
                    <TableRow key={`coach-${coach.id}`} style={{ backgroundColor: 'rgba(8,45,104,0.03)' }}>
                      <TableCell className={classes.cell}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                          <Avatar style={{ width: 28, height: 28, fontSize: '0.6rem', backgroundColor: '#082D68', color: '#F0C040', flexShrink: 0 }}>
                            M
                          </Avatar>
                          <Flag filename={getFlag(coach.country)} country={coach.country} />
                          <Typography style={{ fontSize: '0.78rem', fontWeight: 500, fontStyle: 'italic' }}>
                            {coach.surname} {coach.name}
                          </Typography>
                        </div>
                      </TableCell>
                      <TableCell className={classes.cell} colSpan={2}>
                        <Chip label="All." size="small" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: '#082D68', color: '#fff' }} />
                      </TableCell>
                      <TableCell className={classes.cell} align="center" colSpan={3}>
                        <div style={{ display: 'flex', gap: 4, justifyContent: 'center' }}>
                          <Chip label={`V ${coach.v}`} size="small" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: '#4caf50', color: '#fff' }} />
                          <Chip label={`P ${coach.d}`} size="small" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: '#082D68', color: '#fff' }} />
                          <Chip label={`S ${coach.l}`} size="small" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: '#CA2331', color: '#fff' }} />
                        </div>
                      </TableCell>
                      <TableCell className={classes.cell} colSpan={2} />
                    </TableRow>
                  ))}
                </>
              )}
              <TableRow style={{ backgroundColor: '#fafafa' }}>
                <TableCell className={classes.header}>Giocatore</TableCell>
                <TableCell className={classes.header}>Ruolo</TableCell>
                <TableCell className={classes.header}>#</TableCell>
                <TableCell className={classes.header} align="center">Pres.</TableCell>
                <TableCell className={classes.header} align="center">Gol</TableCell>
                <TableCell className={classes.header} align="center">Amm.</TableCell>
                <TableCell className={classes.header} align="center">Esp.</TableCell>
                <TableCell className={classes.header} align="center"></TableCell>
              </TableRow>
              {players.length > 0 ? (
                players.map((row) => (
                  <React.Fragment key={row.id}>
                  <TableRow className={classes.row} onClick={() => onPlayerSelect(row.id)}>
                    <TableCell className={classes.cell}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                        <Avatar
                          src={row.photo ? `https://www.archiviorossoblu.it/images/giocatori/${row.photo}` : undefined}
                          alt={`${row.surname} ${row.name}`}
                          style={{ width: 28, height: 28, fontSize: '0.6rem', backgroundColor: '#082D68', color: '#fff', flexShrink: 0 }}
                        >{!row.photo && (row.number || '?')}</Avatar>
                        <Flag filename={getFlag(row.country)} country={row.country} />
                        <Typography style={{ fontSize: '0.78rem', fontWeight: 500 }}>{row.surname} {row.name}</Typography>
                      </div>
                    </TableCell>
                    <TableCell className={classes.cell}>
                      <Avatar className={classes.avatar}>{row.roleabbrevation?.[0]?.role}</Avatar>
                    </TableCell>
                    <TableCell className={classes.cell}>
                      <Avatar className={classes.avatarBlue}>{row.number}</Avatar>
                    </TableCell>
                    <TableCell className={classes.cell} align="center">
                      <Chip icon={<EventIcon style={{ fontSize: 12 }} />} label={row.appearances} size="small" color="primary" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700 }} />
                    </TableCell>
                    <TableCell className={classes.cell} align="center">
                      <Chip icon={<SportsSoccerIcon style={{ fontSize: 12 }} />} label={row.goals} size="small" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: '#CA2331', color: '#fff' }} />
                    </TableCell>
                    <TableCell className={classes.cell} align="center">
                      <Chip label={row.yellowcard} size="small" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: '#FDDB3A', color: '#333' }} />
                    </TableCell>
                    <TableCell className={classes.cell} align="center">
                      <Chip label={row.redcard} size="small" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: '#CA2331', color: '#fff' }} />
                    </TableCell>
                    <TableCell className={classes.cell} align="center">
                      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end' }}>
                        {hasCup(row) && (
                          <IconButton
                            size="small"
                            aria-label={expanded.has(row.id) ? 'nascondi dettaglio competizioni' : 'mostra dettaglio competizioni'}
                            aria-expanded={expanded.has(row.id)}
                            onClick={(e) => { e.stopPropagation(); toggleExpanded(row.id); }}
                          >
                            {expanded.has(row.id) ? <KeyboardArrowUpIcon fontSize="small" /> : <KeyboardArrowDownIcon fontSize="small" />}
                          </IconButton>
                        )}
                        <IconButton size="small" aria-label="dettagli" onClick={(e) => { e.stopPropagation(); onPlayerSelect(row.id); }}>
                          <MoreVertIcon fontSize="small" />
                        </IconButton>
                      </div>
                    </TableCell>
                  </TableRow>
                  {hasCup(row) && expanded.has(row.id) && (
                    <>
                      <TableRow className={classes.breakdownRow}>
                        <TableCell className={classes.breakdownLabel} colSpan={3}>{leagueLabel}</TableCell>
                        <TableCell className={classes.breakdownCell} align="center">{num(row.appearances)}</TableCell>
                        <TableCell className={classes.breakdownCell} align="center">{num(row.goals)}</TableCell>
                        <TableCell className={classes.breakdownCell} align="center">{num(row.yellowcard)}</TableCell>
                        <TableCell className={classes.breakdownCell} align="center">{num(row.redcard)}</TableCell>
                        <TableCell className={classes.breakdownCell} />
                      </TableRow>
                      <TableRow className={classes.breakdownRow}>
                        <TableCell className={classes.breakdownLabel} colSpan={3}>Coppa Italia</TableCell>
                        <TableCell className={classes.breakdownCell} align="center">{num(row.ci.appearances)}</TableCell>
                        <TableCell className={classes.breakdownCell} align="center">{num(row.ci.goals)}</TableCell>
                        <TableCell className={classes.breakdownCell} align="center">{num(row.ci.yellowcard)}</TableCell>
                        <TableCell className={classes.breakdownCell} align="center">{num(row.ci.redcard)}</TableCell>
                        <TableCell className={classes.breakdownCell} />
                      </TableRow>
                      <TableRow className={classes.breakdownTotalRow}>
                        <TableCell className={classes.breakdownLabel} colSpan={3}>Totale</TableCell>
                        <TableCell className={classes.breakdownCell} align="center"><b>{num(row.appearances) + num(row.ci.appearances)}</b></TableCell>
                        <TableCell className={classes.breakdownCell} align="center"><b>{num(row.goals) + num(row.ci.goals)}</b></TableCell>
                        <TableCell className={classes.breakdownCell} align="center"><b>{num(row.yellowcard) + num(row.ci.yellowcard)}</b></TableCell>
                        <TableCell className={classes.breakdownCell} align="center"><b>{num(row.redcard) + num(row.ci.redcard)}</b></TableCell>
                        <TableCell className={classes.breakdownCell} />
                      </TableRow>
                    </>
                  )}
                  </React.Fragment>
                ))
              ) : seasonID > 0 ? (
                Array.from({ length: 5 }).map((_, i) => (
                  <TableRow key={i}>
                    <TableCell colSpan={8}>
                      <Skeleton animation="wave" height={32} />
                    </TableCell>
                  </TableRow>
                ))
              ) : (
                <TableRow>
                  <TableCell colSpan={8} align="center">
                    <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.45)' }}>Seleziona una stagione</Typography>
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </CardContent>
    </Card>
  );
}
