import React from 'react';
import { getFlagUrl } from '../utils/flagMap';

/**
 * Bandiera nazione.
 * Props:
 *   filename  - valore del campo flag in allCountries (es. "it.png")
 *   country   - nome nazione, usato come alt text
 *   size      - "sm" (default) | "md"
 */
export default function Flag({ filename, country = '', size = 'sm' }) {
  const width  = size === 'md' ? 28 : 22;
  const height = size === 'md' ? 19 : 15;

  return (
    <img
      src={getFlagUrl(filename)}
      alt={country}
      width={width}
      height={height}
      style={{
        borderRadius: 3,
        border: '1px solid rgba(0,0,0,0.12)',
        boxShadow: '0 1px 3px rgba(0,0,0,0.18)',
        objectFit: 'cover',
        flexShrink: 0,
        display: 'inline-block',
        verticalAlign: 'middle',
      }}
    />
  );
}
