import React, { useState } from 'react';
import { trackCardClick } from '../../utils/analytics';
import { makeStyles } from '@mui/styles';
import SectionLabel from '../SectionLabel';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardMedia from '@mui/material/CardMedia';
import CardContent from '@mui/material/CardContent';
import CardActions from '@mui/material/CardActions';
import Typography from '@mui/material/Typography';
import Avatar from '@mui/material/Avatar';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import IconButton from '@mui/material/IconButton';
import { allTeams } from '../../utils/generals'
import MatchReport from '../dialogs/MatchReport'
import { parseMatchReport } from '../../utils/matchReport'
import Moment from 'react-moment';
import 'moment/locale/it';

const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
    height: '100%',
    display: 'flex',
    flexDirection: 'column',
  },
  media: {
    height: 0,
    paddingTop: '42%',
  },
  content: {
    flex: 1,
    padding: theme.spacing(0, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  infoRow: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.5, 1),
  },
  infoText: {
    fontSize: '0.78rem',
    fontWeight: 500,
    flex: 1,
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
  },
  reportRow: {
    display: 'flex',
    alignItems: 'flex-start',
    gap: theme.spacing(0.75),
    padding: theme.spacing(0.4, 1),
  },
  reportLabel: {
    fontSize: '0.7rem',
    fontWeight: 700,
    flexShrink: 0,
    color: '#082D68',
    paddingTop: 1,
  },
  reportText: {
    fontSize: '0.75rem',
    color: 'rgba(0,0,0,0.65)',
    lineHeight: 1.4,
  },
  scoreboard: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: theme.spacing(1.5, 2, 1),
    background: 'linear-gradient(135deg, #082D68 0%, #0d3d8f 100%)',
    width: '100%',
    boxSizing: 'border-box',
  },
  teamBlock: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    gap: 4,
    flex: 1,
  },
  teamLogo: {
    width: 40,
    height: 40,
  },
  teamName: {
    fontSize: '0.62rem',
    fontWeight: 700,
    color: '#fff',
    textAlign: 'center',
    maxWidth: 72,
  },
  scoreCenter: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    flex: '0 0 auto',
    gap: 4,
    padding: theme.spacing(0, 1),
  },
  score: {
    fontWeight: 800,
    fontSize: '1.8rem',
    color: '#F0C040',
    letterSpacing: 2,
  },
  vs: {
    fontWeight: 800,
    fontSize: '1rem',
    color: '#F0C040',
  },
  stadioAvatar: {
    width: 20,
    height: 20,
    fontSize: '0.5rem',
    fontWeight: 700,
    backgroundColor: '#082D68',
    color: '#fff',
    flexShrink: 0,
  },
}));

export default function Match({ match, title }) {
  const classes = useStyles();

  const matchTitle = (match.played === 'Y')
    ? `${match.home} ${match.goalshome} - ${match.goalsaway} ${match.away}`
    : `${match.home} VS ${match.away}`;
  const homeTeam = allTeams.filter((team) => team.name === match.home);
  const awayTeam = allTeams.filter((team) => team.name === match.away);

  const [openLastMatch, setLastMatchOpen] = useState(false);
  const handleClickOpen = () => { setLastMatchOpen(true); trackCardClick(`match_${title.toLowerCase().replace(/\s+/g, '_')}`); };
  const handleClose = () => setLastMatchOpen(false);

  const FALLBACK_LOGO = 'https://www.archiviorossoblu.it/images/squadre/default.png';
  const imageHome = homeTeam[0]
    ? `https://www.archiviorossoblu.it/images/squadre/${homeTeam[0].photo}`
    : FALLBACK_LOGO;
  const imageAway = awayTeam[0]
    ? `https://www.archiviorossoblu.it/images/squadre/${awayTeam[0].photo}`
    : FALLBACK_LOGO;
  const image = (match.photo !== '')
    ? `https://www.archiviorossoblu.it/images/partite/${match.photo}`
    : 'https://www.archiviorossoblu.it/images/sfondo-campo.jpg';

  const homeId = homeTeam[0]?.id ?? null;
  const awayId = awayTeam[0]?.id ?? null;
  const opponentTeamId = homeId === '13' ? awayId : homeId;
  const isCagliariHome = homeId === '13';
  const getResult = () => {
    if (match.played !== 'Y') return null;
    const cag = isCagliariHome ? parseInt(match.goalshome) : parseInt(match.goalsaway);
    const opp = isCagliariHome ? parseInt(match.goalsaway) : parseInt(match.goalshome);
    if (cag > opp) return { label: 'VITTORIA', color: '#4caf50' };
    if (cag === opp) return { label: 'PAREGGIO', color: '#9e9e9e' };
    return { label: 'SCONFITTA', color: '#CA2331' };
  };
  const result = getResult();

  const parsed = match.played === 'Y' ? parseMatchReport(match.report, match.home, match.away) : {};

  const timePart = match.date?.split(' ')?.[1];
  const hasTime = timePart && timePart !== '00:00:00';

  return (
    <Card className={classes.root}>
      <CardHeader
        action={
          <IconButton aria-label="dettagli" onClick={handleClickOpen}>
            <MoreVertIcon />
          </IconButton>
        }
        avatar={
          <Chip label={title} size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        }
        subheader={
          <span>
            <Moment locale='it' format="LL">{match.date}</Moment>
            {hasTime && (
              <span style={{ marginLeft: 6, color: 'rgba(0,0,0,0.45)', fontSize: '0.8rem' }}>
                ⏰ {timePart.slice(0, 5)}
              </span>
            )}
          </span>
        }
      />
      <CardMedia className={classes.media} image={image} title={matchTitle} />
      <CardActions disableSpacing style={{ padding: 0 }}>
        <div className={classes.scoreboard}>
          <div className={classes.teamBlock}>
            <Avatar src={imageHome} alt={match.home} className={classes.teamLogo} variant="rounded" />
            <Typography className={classes.teamName}>{match.home}</Typography>
          </div>
          <div className={classes.scoreCenter}>
            {match.played === 'Y' ? (
              <Typography className={classes.score}>
                {match.goalshome} — {match.goalsaway}
              </Typography>
            ) : (
              <Typography className={classes.vs}>VS</Typography>
            )}
            {result && (
              <Chip
                label={result.label}
                size="small"
                style={{ fontSize: '0.58rem', height: 18, fontWeight: 800, backgroundColor: result.color, color: '#fff' }}
              />
            )}
          </div>
          <div className={classes.teamBlock}>
            <Avatar src={imageAway} alt={match.away} className={classes.teamLogo} variant="rounded" />
            <Typography className={classes.teamName}>{match.away}</Typography>
          </div>
        </div>
      </CardActions>
      <CardContent className={classes.content}>
        <SectionLabel>Info</SectionLabel>
        <div className={classes.infoRow}>
          <Avatar className={classes.stadioAvatar}><LocationOnIcon style={{ fontSize: 12 }} /></Avatar>
          <Typography className={classes.infoText}>{homeTeam[0].stadium}</Typography>
          <Chip label={`G ${match.day}`} size="small" color="primary" style={{ fontSize: '0.6rem', height: 18, fontWeight: 700 }} />
        </div>
        {(parsed.scorers || parsed.bookings) && (
          <>
            <Divider style={{ margin: '4px 8px' }} />
            {parsed.scorers && (
              <div className={classes.reportRow}>
                <Typography className={classes.reportLabel}>⚽</Typography>
                <Typography className={classes.reportText}>{parsed.scorers}</Typography>
              </div>
            )}
            {parsed.bookings && (
              <div className={classes.reportRow}>
                <Typography className={classes.reportLabel}>🟨</Typography>
                <Typography className={classes.reportText}>{parsed.bookings}</Typography>
              </div>
            )}
          </>
        )}
      </CardContent>
      <MatchReport
        open={openLastMatch}
        handleClose={handleClose}
        title={matchTitle}
        report={match.report}
        played={match.played}
        opponentTeamId={opponentTeamId}
        match={{ ...match, gh: match.goalshome, ga: match.goalsaway }}
      />
    </Card>
  );
}
