import React from 'react';
import { makeStyles } from '@mui/styles';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Skeleton from '@mui/material/Skeleton';
import Typography from '@mui/material/Typography';
import Chip from '@mui/material/Chip';

const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
    height: '100%',
    display: 'flex',
    flexDirection: 'column',
  },
  content: {
    flex: 1,
    overflowY: 'auto',
    padding: theme.spacing(0, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  header: {
    fontSize: '0.72rem',
    fontWeight: 700,
    color: '#082D68',
    padding: '4px 8px',
  },
  row: {
    '&:hover': { backgroundColor: theme.palette.action.hover },
  },
  cell: {
    padding: '4px 8px',
    fontSize: '0.78rem',
  },
}));

export default function Referees({ referees, seasonID, seasonLabel }) {
  const classes = useStyles();

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={<Chip label={seasonLabel || 'Arbitri'} size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />}
        title="Arbitri"
        subheader="Cagliari Calcio"
      />
      <CardContent className={classes.content}>
        <TableContainer>
          <Table stickyHeader size="small" aria-label="arbitri">
            <TableHead>
              <TableRow>
                <TableCell className={classes.header}>Arbitro</TableCell>
                <TableCell className={classes.header} align="center">Partite</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {referees.length > 0 ? (
                referees.map((row) => (
                  <TableRow key={row.id} className={classes.row}>
                    <TableCell className={classes.cell}>
                      <Typography style={{ fontSize: '0.78rem', fontWeight: 500 }}>{row.surname} {row.name}</Typography>
                    </TableCell>
                    <TableCell className={classes.cell} align="center">
                      <Chip label={row.appareances} size="small" color="primary" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700 }} />
                    </TableCell>
                  </TableRow>
                ))
              ) : seasonID > 0 ? (
                Array.from({ length: 3 }).map((_, i) => (
                  <TableRow key={i}>
                    <TableCell colSpan={2}><Skeleton animation="wave" height={32} /></TableCell>
                  </TableRow>
                ))
              ) : (
                <TableRow>
                  <TableCell colSpan={2} align="center">
                    <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.45)' }}>Seleziona una stagione</Typography>
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </CardContent>
    </Card>
  );
}
