/**
 * Dato il filename della bandiera (da generals.js allCountries),
 * restituisce l'URL dell'SVG da flagcdn.com.
 * Fallback: immagine dal server originale.
 */
export const getFlagUrl = (filename) => {
  const iso = flagMap[filename];
  if (iso) return `https://flagcdn.com/${iso}.svg`;
  // fallback al server originale
  return `https://www.archiviorossoblu.it/images/nazioni/${filename}`;
};
