import React, { useRef } from 'react';
import { makeStyles } from '@mui/styles';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Box from '@mui/material/Box';
import Divider from '@mui/material/Divider';
import Tooltip from '@mui/material/Tooltip';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Skeleton from '@mui/material/Skeleton';
import Typography from '@mui/material/Typography';
import Avatar from '@mui/material/Avatar';
import Chip from '@mui/material/Chip';
import IconButton from '@mui/material/IconButton';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import Moment from 'react-moment';


const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
    height: '100%',
    display: 'flex',
    flexDirection: 'column',
  },
  content: {
    flex: 1,
    overflowY: 'auto',
    padding: theme.spacing(0, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  // Campionato
  headerCamp: {
    fontSize: '0.72rem',
    fontWeight: 700,
    color: '#082D68',
    padding: '6px 8px',
    backgroundColor: theme.palette.background.paper,
  },
  rowCamp: {
    cursor: 'pointer',
    '&:hover': { backgroundColor: 'rgba(8,45,104,0.04)' },
  },
  sectionCamp: {
    fontSize: '0.65rem',
    fontWeight: 800,
    letterSpacing: '0.08em',
    textTransform: 'uppercase',
    color: '#082D68',
    padding: '6px 8px 2px',
    backgroundColor: 'rgba(8,45,104,0.05)',
    borderBottom: 'none',
  },
  // Coppa Italia
  headerCoppa: {
    fontSize: '0.72rem',
    fontWeight: 700,
    color: '#8B6914',
    padding: '6px 8px',
    backgroundColor: theme.palette.background.paper,
  },
  rowCoppa: {
    backgroundColor: 'rgba(240,192,64,0.04)',
    '&:hover': { backgroundColor: 'rgba(240,192,64,0.10)' },
  },
  sectionCoppa: {
    fontSize: '0.65rem',
    fontWeight: 800,
    letterSpacing: '0.08em',
    textTransform: 'uppercase',
    color: '#8B6914',
    padding: '6px 8px 2px',
    backgroundColor: 'rgba(240,192,64,0.08)',
    borderBottom: 'none',
    borderTop: '1px solid rgba(240,192,64,0.25)',
  },
  // Coppe europee
  headerEuro: {
    fontSize: '0.72rem',
    fontWeight: 700,
    color: '#1a5e1a',
    padding: '6px 8px',
    backgroundColor: theme.palette.background.paper,
  },
  rowEuro: {
    backgroundColor: 'rgba(76,175,80,0.04)',
    '&:hover': { backgroundColor: 'rgba(76,175,80,0.10)' },
  },
  sectionEuro: {
    fontSize: '0.65rem',
    fontWeight: 800,
    letterSpacing: '0.08em',
    textTransform: 'uppercase',
    color: '#1a5e1a',
    padding: '6px 8px 2px',
    backgroundColor: 'rgba(76,175,80,0.08)',
    borderBottom: 'none',
    borderTop: '1px solid rgba(76,175,80,0.25)',
  },
  cell: {
    padding: '6px 8px',
    fontSize: '0.78rem',
  },
  avatarBlue: {
    width: 22,
    height: 22,
    fontSize: '0.6rem',
    fontWeight: 700,
    backgroundColor: '#082D68',
    color: '#fff',
  },
}));

function resultChip(row) {
  if (row.played !== 'Y') return null;
  const isCagliariHome = row.home === 'Cagliari';
  const cag = isCagliariHome ? parseInt(row.gh) : parseInt(row.ga);
  const opp = isCagliariHome ? parseInt(row.ga) : parseInt(row.gh);
  const { label, color } = cag > opp
    ? { label: 'V', color: '#4caf50' }
    : cag === opp
    ? { label: 'P', color: '#9e9e9e' }
    : { label: 'S', color: '#CA2331' };
  return <Chip label={label} size="small" style={{ fontSize: '0.6rem', height: 18, fontWeight: 800, backgroundColor: color, color: '#fff' }} />;
}

export default function MatchesPanel({ matches = [], cupMatches = [], seasonID, seasonLabel, onMatchSelect }) {
  const classes = useStyles();
  const contentRef = useRef(null);
  const sectionRefs = useRef({});

  const scrollTo = (key) => {
    const el = sectionRefs.current[key];
    const container = contentRef.current;
    if (el && container) {
      container.scrollTop = el.offsetTop - container.offsetTop;
    }
  };

  // Raggruppa per competition, mantenendo l'ordine di apparizione
  const cupGroups = cupMatches.reduce((acc, m) => {
    const key = m.competition || (m.europe === 'Y' ? 'Coppa Europea' : 'Coppa Italia');
    if (!acc[key]) acc[key] = { isEuro: m.europe === 'Y', matches: [] };
    acc[key].matches.push(m);
    return acc;
  }, {});

  const showSkeleton = seasonID > 0;

  // Chip legenda: campionato sempre presente + una per ogni coppa
  const legendChips = [
    { key: 'campionato', label: 'Campionato', count: matches.length, color: '#082D68', textColor: '#fff' },
    ...Object.entries(cupGroups).map(([name, group]) => ({
      key: name,
      label: name,
      count: group.matches.length,
      color: group.isEuro ? '#4caf50' : '#F0C040',
      textColor: group.isEuro ? '#fff' : '#082D68',
    })),
  ];

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={<Chip label={seasonLabel || 'Partite'} size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />}
        title="Partite"
        subheader="Cagliari Calcio"
      />
      {legendChips.length > 0 && (
        <>
          <Box style={{ display: 'flex', flexWrap: 'wrap', gap: 6, padding: '6px 12px 8px' }}>
            {legendChips.map(({ key, label, count, color, textColor }) => (
              <Tooltip key={key} title={`Vai a ${label}`} placement="top">
                <Chip
                  label={`${label} (${count})`}
                  size="small"
                  onClick={() => scrollTo(key)}
                  style={{ fontWeight: 700, fontSize: '0.68rem', backgroundColor: color, color: textColor, cursor: 'pointer' }}
                />
              </Tooltip>
            ))}
          </Box>
          <Divider />
        </>
      )}
      <CardContent className={classes.content} ref={contentRef}>
        <TableContainer>
          <Table stickyHeader size="small">
            <TableHead>
              <TableRow>
                <TableCell className={classes.headerCamp}>G / Turno</TableCell>
                <TableCell className={classes.headerCamp}>Data</TableCell>
                <TableCell className={classes.headerCamp}>Partita</TableCell>
                <TableCell className={classes.headerCamp}>Ris.</TableCell>
                <TableCell className={classes.headerCamp} />
              </TableRow>
            </TableHead>
            <TableBody>

              {/* ── CAMPIONATO ── */}
              <TableRow ref={el => sectionRefs.current['campionato'] = el}>
                <TableCell colSpan={5} className={classes.sectionCamp}>Campionato</TableCell>
              </TableRow>
              {matches.length > 0 ? matches.map(row => (
                <TableRow key={`camp-${row.id}`} className={classes.rowCamp} onClick={() => onMatchSelect(row.id)}>
                  <TableCell className={classes.cell}>
                    <Avatar className={classes.avatarBlue}>{row.day}</Avatar>
                  </TableCell>
                  <TableCell className={classes.cell}>
                    <Typography style={{ fontSize: '0.75rem', color: 'rgba(0,0,0,0.45)' }}>
                      <Moment locale="it" format="DD/MM/YY">{row.date}</Moment>
                    </Typography>
                  </TableCell>
                  <TableCell className={classes.cell}>
                    <Typography style={{ fontSize: '0.78rem', fontWeight: 500 }}>
                      {row.played === 'Y'
                        ? `${row.home} ${row.gh} - ${row.ga} ${row.away}`
                        : `${row.home} vs ${row.away}`}
                    </Typography>
                  </TableCell>
                  <TableCell className={classes.cell}>{resultChip(row)}</TableCell>
                  <TableCell className={classes.cell} align="center">
                    <IconButton size="small" onClick={e => { e.stopPropagation(); onMatchSelect(row.id); }}>
                      <MoreVertIcon fontSize="small" />
                    </IconButton>
                  </TableCell>
                </TableRow>
              )) : showSkeleton ? (
                Array.from({ length: 5 }).map((_, i) => (
                  <TableRow key={`skel-camp-${i}`}>
                    <TableCell colSpan={5}><Skeleton animation="wave" height={32} /></TableCell>
                  </TableRow>
                ))
              ) : (
                <TableRow>
                  <TableCell colSpan={5} align="center">
                    <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.45)' }}>Seleziona una stagione</Typography>
                  </TableCell>
                </TableRow>
              )}

              {/* ── COPPE (raggruppate per competition) ── */}
              {Object.entries(cupGroups).map(([name, group]) => (
                <React.Fragment key={name}>
                  <TableRow ref={el => sectionRefs.current[name] = el}>
                    <TableCell colSpan={5} className={group.isEuro ? classes.sectionEuro : classes.sectionCoppa}>
                      {name}
                    </TableCell>
                  </TableRow>
                  {group.matches.map(row => (
                    <TableRow key={`cup-${row.id}`} className={group.isEuro ? classes.rowEuro : classes.rowCoppa}>
                      <TableCell className={classes.cell}>
                        <Typography style={{ fontSize: '0.72rem', color: group.isEuro ? '#1a5e1a' : '#8B6914', fontWeight: 600 }}>
                          {row.description}
                        </Typography>
                      </TableCell>
                      <TableCell className={classes.cell}>
                        <Typography style={{ fontSize: '0.75rem', color: 'rgba(0,0,0,0.45)' }}>
                          <Moment locale="it" format="DD/MM/YY">{row.date}</Moment>
                        </Typography>
                      </TableCell>
                      <TableCell className={classes.cell}>
                        <Typography style={{ fontSize: '0.78rem', fontWeight: 500 }}>
                          {row.played === 'Y'
                            ? `${row.home} ${row.gh} - ${row.ga} ${row.away}`
                            : `${row.home} vs ${row.away}`}
                        </Typography>
                      </TableCell>
                      <TableCell className={classes.cell}>{resultChip(row)}</TableCell>
                      <TableCell className={classes.cell} />
                    </TableRow>
                  ))}
                </React.Fragment>
              ))}

            </TableBody>
          </Table>
        </TableContainer>
      </CardContent>
    </Card>
  );
}
