import React, { useState, useEffect } from 'react';
import PropTypes from 'prop-types';
import { makeStyles, withStyles, useTheme } from '@mui/styles';
import { alpha } from '@mui/material/styles';
import * as ARBApi from '../utils/ARBApi'
import MatchReport from '../components/dialogs/MatchReport'
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Table from '@mui/material/Table';
import TableHead from '@mui/material/TableHead';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableFooter from '@mui/material/TableFooter';
import TablePagination from '@mui/material/TablePagination';
import TableRow from '@mui/material/TableRow';
import Typography from '@mui/material/Typography';
import Avatar from '@mui/material/Avatar';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import NativeSelect from '@mui/material/NativeSelect';
import IconButton from '@mui/material/IconButton';
import FirstPageIcon from '@mui/icons-material/FirstPage';
import KeyboardArrowLeft from '@mui/icons-material/KeyboardArrowLeft';
import KeyboardArrowRight from '@mui/icons-material/KeyboardArrowRight';
import LastPageIcon from '@mui/icons-material/LastPage';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import SportsSoccerIcon from '@mui/icons-material/SportsSoccer';
import { allTeams, allSeasons } from '../utils/generals'
import Moment from 'react-moment';
import 'moment/locale/it';
import sortBy from 'sort-by'

const StyledTableRow = withStyles((theme) => ({
  root: {
    cursor: 'pointer',
    '&:nth-of-type(odd)': {
      backgroundColor: theme.palette.action.hover,
    },
    '&:hover': {
      backgroundColor: alpha(theme.palette.primary.main, 0.08),
    },
  }
}))(TableRow);

const useStyles1 = makeStyles((theme) => ({
  root: { flexShrink: 0, marginLeft: theme.spacing(2.5) },
}));

function TablePaginationActions(props) {
  const classes = useStyles1();
  const theme = useTheme();
  const { count, page, rowsPerPage, onPageChange } = props;

  return (
    <div className={classes.root}>
      <IconButton onClick={(e) => onPageChange(e, 0)} disabled={page === 0} aria-label="first page">
        {theme.direction === 'rtl' ? <LastPageIcon /> : <FirstPageIcon />}
      </IconButton>
      <IconButton onClick={(e) => onPageChange(e, page - 1)} disabled={page === 0} aria-label="previous page">
        {theme.direction === 'rtl' ? <KeyboardArrowRight /> : <KeyboardArrowLeft />}
      </IconButton>
      <IconButton onClick={(e) => onPageChange(e, page + 1)} disabled={page >= Math.ceil(count / rowsPerPage) - 1} aria-label="next page">
        {theme.direction === 'rtl' ? <KeyboardArrowLeft /> : <KeyboardArrowRight />}
      </IconButton>
      <IconButton onClick={(e) => onPageChange(e, Math.max(0, Math.ceil(count / rowsPerPage) - 1))} disabled={page >= Math.ceil(count / rowsPerPage) - 1} aria-label="last page">
        {theme.direction === 'rtl' ? <FirstPageIcon /> : <LastPageIcon />}
      </IconButton>
    </div>
  );
}

TablePaginationActions.propTypes = {
  count: PropTypes.number.isRequired,
  onPageChange: PropTypes.func.isRequired,
  page: PropTypes.number.isRequired,
  rowsPerPage: PropTypes.number.isRequired,
};

const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
  },
  content: {
    padding: theme.spacing(0, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  sectionLabel: {
    fontSize: '0.65rem',
    fontWeight: 800,
    letterSpacing: '0.08em',
    textTransform: 'uppercase',
    color: theme.palette.primary.main,
    padding: theme.spacing(1, 1, 0.25),
  },
  selectBar: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.5, 1),
    borderRadius: 6,
    backgroundColor: alpha(theme.palette.primary.main, 0.06),
    margin: theme.spacing(0.5, 1, 1),
  },
  header: {
    fontWeight: 700,
    fontSize: '0.75rem',
  },
  seasonAvatar: {
    backgroundColor: '#082D68',
    color: '#FFFFFF',
    width: 32,
    height: 32,
    fontSize: '0.65rem',
    fontWeight: 700,
  },
  matchText: {
    fontSize: '0.85rem',
    color: '#082D68',
    fontWeight: 500,
  },
}));

export default function SearchMatchesDetails() {
  const classes = useStyles();
  const [match, setMatch] = useState(0);
  const [matchOpen, setMatchOpen] = useState(false);
  const [page, setPage] = useState(0);
  const rowsPerPage = 8;
  const [teamId, setTeamId] = useState(() => {
    const teams = allTeams.filter(t => t.name !== 'Cagliari');
    return teams[Math.floor(Math.random() * teams.length)]?.id ?? 0;
  });
  const [matches, setMatches] = useState([]);

  useEffect(() => {
    if (teamId) {
      ARBApi.getAllByID('matchesTeam', teamId).then(setMatches);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleChange = (value) => {
    setTeamId(value);
    setPage(0);
    ARBApi.getAllByID(`matchesTeam`, value).then((matches) => {
      setMatches(matches);
    });
  };

  const handleChangePage = (event, newPage) => { setPage(newPage); };

  const handleClickCloseMatch = () => {
    setMatchOpen(false);
    setMatch(0);
  };

  const onSelectMatch = (id) => {
    let [m] = matches.filter((match) => match.id === id);
    const [team] = (m.home === 'Cagliari') ? allTeams.filter((team) => team.name === m.away) : allTeams.filter((team) => team.name === m.home);
    m.opponentTeamId = (m.played === 'Y') ? 0 : team.id;
    m.title = (m.played === 'Y') ? `${m.home} ${m.gh} - ${m.ga} ${m.away}` : `${m.home} VS ${m.away}`;
    setMatch(m);
    setMatchOpen(true);
  };

  allTeams.sort(sortBy('name'));
  matches.map((match) => match.year = allSeasons.filter((season) => season.id === match.ID_S), [allSeasons]);

  const selectedTeam = allTeams.find(t => String(t.id) === String(teamId));

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={
          <Chip label="Partite" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        }
        title="Cerca per squadra"
        subheader={selectedTeam ? `vs ${selectedTeam.name}` : 'Seleziona una squadra'}
      />
      <CardContent className={classes.content}>
        <Typography className={classes.sectionLabel}>Squadra</Typography>
        <div className={classes.selectBar}>
          <SportsSoccerIcon style={{ fontSize: '1rem', color: '#082D68', flexShrink: 0 }} />
          <NativeSelect
            value={teamId}
            onChange={(e) => handleChange(e.target.value)}
            inputProps={{ name: 'team', id: 'team-native-helper' }}
            style={{ flex: 1, fontSize: '0.85rem' }}
            disableUnderline
          >
            <option value="">Seleziona squadra…</option>
            {allTeams.filter((team) => team.name !== 'Cagliari').map((team) => (
              <option value={team.id} key={team.name}>{team.name}</option>
            ))}
          </NativeSelect>
        </div>

        {matches.length > 0 && (
          <>
            <Divider style={{ margin: '4px 0' }} />
            <Typography className={classes.sectionLabel}>
              Risultati — {matches.length} partite
            </Typography>
            <TableContainer>
              <Table stickyHeader size="small">
                <TableHead>
                  <TableRow>
                    <TableCell className={classes.header}>Stagione</TableCell>
                    <TableCell className={classes.header}>Data</TableCell>
                    <TableCell className={classes.header}>Partita</TableCell>
                    <TableCell className={classes.header} align="center"></TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {matches.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage).map((row) => (
                    <StyledTableRow key={row.id} onClick={() => onSelectMatch(row.id)}>
                      <TableCell>
                        <Avatar className={classes.seasonAvatar}>
                          {row.year[0]?.year?.slice(-2) ?? '—'}
                        </Avatar>
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2" color="textSecondary">
                          {row.date !== '0000-00-00 00:00:00'
                            ? <Moment locale='it' format="LL">{row.date}</Moment>
                            : 'ND'}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Typography className={classes.matchText}>
                          {row.home} {row.gh} — {row.ga} {row.away}
                        </Typography>
                      </TableCell>
                      <TableCell align="center">
                        <IconButton size="small" onClick={(e) => { e.stopPropagation(); onSelectMatch(row.id); }}>
                          <MoreVertIcon fontSize="small" />
                        </IconButton>
                      </TableCell>
                    </StyledTableRow>
                  ))}
                </TableBody>
                <TableFooter>
                  <TableRow>
                    <TablePagination
                      rowsPerPageOptions={[8]}
                      colSpan={4}
                      count={matches.length}
                      rowsPerPage={rowsPerPage}
                      page={page}
                      slotProps={{ select: { inputProps: { 'aria-label': 'rows per page' }, native: true } }}
                      onPageChange={handleChangePage}
                      ActionsComponent={TablePaginationActions}
                    />
                  </TableRow>
                </TableFooter>
              </Table>
            </TableContainer>
          </>
        )}
      </CardContent>
      {matchOpen && (
        <MatchReport
          open={matchOpen}
          handleClose={handleClickCloseMatch}
          title={match.title}
          report={match.report}
          played={match.played}
          opponentTeamId={match.opponentTeamId}
          match={match}
        />
      )}
    </Card>
  );
}
