import React, { useState } from 'react';
import { makeStyles } from '@mui/styles';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Typography from '@mui/material/Typography';
import Avatar from '@mui/material/Avatar';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import IconButton from '@mui/material/IconButton';
import Tooltip from '@mui/material/Tooltip';
import EqualizerIcon from '@mui/icons-material/Equalizer';
import { allTeams } from '../utils/generals';
import MatchReport from './dialogs/MatchReport';

const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
  },
  content: {
    padding: theme.spacing(0, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  row: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.6, 1),
    borderRadius: 6,
    cursor: 'pointer',
    '&:hover': {
      backgroundColor: theme.palette.action.hover,
    },
  },
  rankAvatar: {
    width: 22,
    height: 22,
    fontSize: '0.6rem',
    fontWeight: 700,
    backgroundColor: '#CA2331',
    color: '#fff',
    flexShrink: 0,
  },
  teamLogo: {
    width: 24,
    height: 24,
    flexShrink: 0,
  },
  teamName: {
    fontSize: '0.8rem',
    fontWeight: 500,
    flex: 1,
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
  },
  statChip: {
    fontSize: '0.6rem',
    height: 18,
    fontWeight: 700,
    flexShrink: 0,
  },
}));

export default function StatsTeams() {
  const classes = useStyles();
  const [openMatch, setMatchOpen] = useState(false);
  const [opponentTeamId, setOpponentTeamId] = useState(0);
  const [opponentTeam, setOpponentTeam] = useState('');
  const items = 10;

  const handleClickCloseMatch = () => {
    setMatchOpen(false);
    setOpponentTeamId(0);
    setOpponentTeam('');
  };

  const changeMatch = (id, team) => {
    if (id > 0) {
      setMatchOpen(true);
      setOpponentTeamId(id);
      setOpponentTeam(team);
    }
  };

  const teamsAvailable = allTeams
    .filter((team) => team.photostadium !== '' && team.name !== 'Cagliari')
    .slice(0, items);

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={
          <Chip label={`TOP #${items} Squadre`} size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        }
        subheader="Squadre più affrontate"
      />
      <CardContent className={classes.content}>
        {teamsAvailable.map((team, i) => {
          const logoUrl = `https://www.archiviorossoblu.it/images/squadre/${team.photo}`;
          return (
            <React.Fragment key={team.id}>
              {i > 0 && <Divider style={{ margin: '2px 0' }} />}
              <div className={classes.row} onClick={() => changeMatch(team.id, team.name)}>
                <Avatar className={classes.rankAvatar}>{i + 1}</Avatar>
                <Avatar src={logoUrl} alt={team.name} className={classes.teamLogo} variant="rounded" />
                <Typography className={classes.teamName}>{team.name}</Typography>
                <Chip
                  label={`${team.matches} partite`}
                  size="small"
                  color="primary"
                  className={classes.statChip}
                />
                <Tooltip title="Statistiche vs squadra" arrow>
                  <IconButton size="small" onClick={(e) => { e.stopPropagation(); changeMatch(team.id, team.name); }}>
                    <EqualizerIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
              </div>
            </React.Fragment>
          );
        })}
      </CardContent>
      {openMatch && (
        <MatchReport
          open={openMatch}
          handleClose={handleClickCloseMatch}
          title={`vs ${opponentTeam}`}
          report={''}
          played={'N'}
          opponentTeamId={opponentTeamId}
        />
      )}
    </Card>
  );
}
