import React from 'react';
import Breadcrumbs from '@mui/material/Breadcrumbs';
import Link from '@mui/material/Link';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';
import NavigateNextIcon from '@mui/icons-material/NavigateNext';

/**
 * items: [{ label: string, href?: string }]
 * Last item without href is rendered as plain text (current page).
 */
export default function Breadcrumb({ items = [] }) {
  return (
    <Box mb={1.5}>
      <Breadcrumbs separator={<NavigateNextIcon fontSize="small" />} aria-label="breadcrumb">
        {items.map((item, i) => {
          const isLast = i === items.length - 1;
          if (isLast || !item.href) {
            return (
              <Typography key={i} style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.5)', fontWeight: 500 }}>
                {item.label}
              </Typography>
            );
          }
          return (
            <Link key={i} href={item.href} underline="hover" style={{ fontSize: '0.78rem', color: '#082D68', fontWeight: 600 }}>
              {item.label}
            </Link>
          );
        })}
      </Breadcrumbs>
    </Box>
  );
}
