import React, { Suspense, lazy } from 'react';
import { createRoot } from 'react-dom/client';
import './index.css';
import { Seasons } from './pages';
import ErrorBoundary from './components/ErrorBoundary';
import ScrollToTop from './components/ScrollToTop';
import * as serviceWorker from './serviceWorker';
import { ThemeProvider, createTheme, StyledEngineProvider } from '@mui/material/styles'
import { ThemeProvider as MuiStylesThemeProvider } from '@mui/styles'
import CssBaseline from '@mui/material/CssBaseline'
import { BrowserRouter, Routes, Route, Navigate, useParams } from 'react-router-dom'
import { HelmetProvider } from 'react-helmet-async'

function RedirectPlayer() {
  const { slug, id } = useParams();
  return <Navigate to={`/cagliari-calcio/giocatore/${slug}/${id}`} replace />;
}

const Stats      = lazy(() => import('./pages/Stats'));
const Players    = lazy(() => import('./pages/Players'));
const Matches    = lazy(() => import('./pages/Matches'));
const Who        = lazy(() => import('./pages/Who'));
const Privacy    = lazy(() => import('./pages/Privacy'));
const PlayerPage = lazy(() => import('./pages/PlayerPage'));
const News        = lazy(() => import('./pages/News'));
const CoachesPage  = lazy(() => import('./pages/CoachesPage'));
const RefereesPage = lazy(() => import('./pages/RefereesPage'));
const ComparePage   = lazy(() => import('./pages/ComparePage'));
const PalmaresPage  = lazy(() => import('./pages/PalmaresPage'));
const LeaguePage    = lazy(() => import('./pages/LeaguePage'));
const AllTimeXIPage = lazy(() => import('./pages/AllTimeXIPage'));

const theme = createTheme({
  palette: {
    primary: {
      main: '#082D68',
      contrastText: '#FFFFFF',
    },
    secondary: {
      main: '#CA2331',
      contrastText: '#FFFFFF',
    },
    background: {
      default: '#f5f7fa',
      paper: '#ffffff',
    },
    common: {
      facebook: '#1877F2',
      twitter: '#1DA1F2',
      linkedin: '#0A66C2',
    },
  },
  typography: {
    fontFamily: '"Inter", "Roboto", "Helvetica", "Arial", sans-serif',
    h6: { fontWeight: 600 },
    subtitle1: { fontWeight: 500 },
    subtitle2: { fontWeight: 500 },
  },
  shape: {
    borderRadius: 8,
  },
  components: {
    MuiAppBar: {
      styleOverrides: {
        root: {
          boxShadow: '0 2px 8px rgba(8, 45, 104, 0.25)',
        },
      },
    },
    MuiPaper: {
      styleOverrides: {
        elevation1: {
          boxShadow: '0 2px 10px rgba(0,0,0,0.07)',
        },
      },
    },
    MuiCard: {
      styleOverrides: {
        root: {
          borderRadius: 12,
          boxShadow: '0 2px 12px rgba(0,0,0,0.08)',
          transition: 'box-shadow 0.2s ease',
          '&:hover': {
            boxShadow: '0 4px 20px rgba(8, 45, 104, 0.15)',
          },
        },
      },
    },
    MuiButton: {
      styleOverrides: {
        root: {
          textTransform: 'none',
          fontWeight: 600,
          borderRadius: 8,
        },
      },
    },
    MuiTableCell: {
      styleOverrides: {
        head: {
          fontWeight: 700,
          fontSize: '0.75rem',
          letterSpacing: '0.04em',
          textTransform: 'uppercase',
        },
      },
    },
    MuiDrawer: {
      styleOverrides: {
        paper: {
          borderRadius: '0 16px 16px 0',
        },
      },
    },
    MuiDialog: {
      styleOverrides: {
        paper: {
          borderRadius: 12,
        },
      },
    },
    MuiTab: {
      styleOverrides: {
        root: {
          textTransform: 'none',
          fontWeight: 600,
          minWidth: 80,
        },
      },
    },
    MuiAvatar: {
      styleOverrides: {
        root: {
          fontWeight: 700,
        },
      },
    },
  },
})

const root = createRoot(document.getElementById('root'));
root.render(
  <HelmetProvider>
  <StyledEngineProvider injectFirst>
    <ThemeProvider theme={theme}>
      <MuiStylesThemeProvider theme={theme}>
        <CssBaseline />
        <BrowserRouter>
          <ErrorBoundary>
            <ScrollToTop />
            <Suspense fallback={null}>
              <Routes>
                <Route path="/" element={<Seasons />} />
                <Route path="/cagliari-calcio" element={<Seasons />} />
                <Route path="/cagliari-calcio/stagioni" element={<Seasons />} />
                <Route path="/cagliari-calcio/statistiche" element={<Stats />} />
                <Route path="/cagliari-calcio/giocatori" element={<Players />} />
                <Route path="/cagliari-calcio/partite" element={<Matches />} />
                <Route path="/cagliari-calcio/chisiamo" element={<Who />} />
                <Route path="/cagliari-calcio/privacy" element={<Privacy />} />
                <Route path="/cagliari-calcio/news" element={<News />} />
                <Route path="/cagliari-calcio/allenatori" element={<CoachesPage />} />
                <Route path="/cagliari-calcio/arbitri" element={<RefereesPage />} />
                <Route path="/cagliari-calcio/confronto" element={<ComparePage />} />
                <Route path="/cagliari-calcio/palmares" element={<PalmaresPage />} />
                <Route path="/cagliari-calcio/xi-di-tutti-i-tempi" element={<AllTimeXIPage />} />
                <Route path="/cagliari-calcio/stagioni/:league" element={<LeaguePage />} />
                <Route path="/cagliari-calcio/giocatore/:slug/:id" element={<PlayerPage />} />
                {/* Redirect old URLs without /cagliari-calcio/ prefix */}
                <Route path="/home" element={<Navigate to="/" replace />} />
                <Route path="/referees" element={<Navigate to="/cagliari-calcio/arbitri" replace />} />
                <Route path="/giocatore/:slug/:id" element={<RedirectPlayer />} />
              </Routes>
            </Suspense>
          </ErrorBoundary>
        </BrowserRouter>
      </MuiStylesThemeProvider>
    </ThemeProvider>
  </StyledEngineProvider>
  </HelmetProvider>
);

// If you want your app to work offline and load faster, you can change
// unregister() to register() below. Note this comes with some pitfalls.
// Learn more about service workers: https://bit.ly/CRA-PWA
serviceWorker.unregister();
