import React from 'react';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import CardActions from '@mui/material/CardActions';
import Box from '@mui/material/Box';
import Skeleton from '@mui/material/Skeleton';

// Match card skeleton: header + media + dark scoreboard + info rows
function MatchSkeleton() {
  return (
    <Card style={{ borderTop: '4px solid #CA2331', height: '100%' }}>
      <CardHeader
        avatar={<Skeleton variant="rounded" width={72} height={24} />}
        title={null}
        subheader={<Skeleton width="50%" height={14} />}
        action={<Skeleton variant="circular" width={32} height={32} style={{ margin: 8 }} />}
      />
      <Skeleton variant="rectangular" style={{ paddingTop: '42%' }} />
      <Box style={{ background: '#082D68', padding: '12px 16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 8 }}>
        <Box display="flex" flexDirection="column" alignItems="center" gap={1} flex={1}>
          <Skeleton variant="circular" width={40} height={40} style={{ backgroundColor: 'rgba(255,255,255,0.15)' }} />
          <Skeleton width={56} height={10} style={{ backgroundColor: 'rgba(255,255,255,0.15)' }} />
        </Box>
        <Skeleton width={48} height={32} style={{ backgroundColor: 'rgba(255,255,255,0.15)' }} />
        <Box display="flex" flexDirection="column" alignItems="center" gap={1} flex={1}>
          <Skeleton variant="circular" width={40} height={40} style={{ backgroundColor: 'rgba(255,255,255,0.15)' }} />
          <Skeleton width={56} height={10} style={{ backgroundColor: 'rgba(255,255,255,0.15)' }} />
        </Box>
      </Box>
      <CardContent style={{ padding: '8px 16px' }}>
        <Skeleton width="30%" height={12} style={{ marginBottom: 8 }} />
        <Box display="flex" alignItems="center" gap={1}>
          <Skeleton variant="circular" width={22} height={22} />
          <Skeleton width="70%" height={14} />
        </Box>
      </CardContent>
    </Card>
  );
}

// Player card skeleton: header + media (56%) + info rows + actions
function PlayerSkeleton() {
  return (
    <Card style={{ borderTop: '4px solid #CA2331', height: '100%' }}>
      <CardHeader
        avatar={<Skeleton variant="rounded" width={80} height={24} />}
        title={<Skeleton width="60%" height={16} />}
        subheader={<Skeleton width="35%" height={12} />}
        action={<Skeleton variant="circular" width={32} height={32} style={{ margin: 8 }} />}
      />
      <Skeleton variant="rectangular" style={{ paddingTop: '56.25%' }} />
      <CardContent style={{ padding: '8px 16px' }}>
        <Skeleton width="25%" height={12} style={{ marginBottom: 8 }} />
        <Box display="flex" alignItems="center" gap={1} mb={1}>
          <Skeleton variant="circular" width={22} height={22} />
          <Skeleton width="60%" height={14} />
        </Box>
        <Box display="flex" alignItems="center" gap={1}>
          <Skeleton variant="circular" width={22} height={22} />
          <Skeleton width="50%" height={14} />
        </Box>
      </CardContent>
      <CardActions style={{ padding: '8px 16px', justifyContent: 'flex-end' }}>
        <Skeleton variant="rounded" width={90} height={24} />
      </CardActions>
    </Card>
  );
}

// List card skeleton: header + list rows (no media)
function ListSkeleton() {
  return (
    <Card style={{ borderTop: '4px solid #CA2331', height: '100%' }}>
      <CardHeader
        avatar={<Skeleton variant="rounded" width={80} height={24} />}
        subheader={<Skeleton width="40%" height={12} />}
      />
      <CardContent style={{ padding: '0 8px 8px' }}>
        {[...Array(5)].map((_, i) => (
          <Box key={i} display="flex" alignItems="center" gap={1} style={{ padding: '8px 8px' }}>
            <Skeleton variant="circular" width={28} height={28} />
            <Skeleton width="65%" height={14} />
            <Skeleton variant="rounded" width={40} height={20} style={{ marginLeft: 'auto' }} />
          </Box>
        ))}
      </CardContent>
    </Card>
  );
}

export default function CardWaiting({ variant = 'player' }) {
  if (variant === 'match') return <MatchSkeleton />;
  if (variant === 'list')  return <ListSkeleton />;
  return <PlayerSkeleton />;
}
