import React, { useState } from 'react';
import { trackCardClick } from '../../utils/analytics';
import { makeStyles } from '@mui/styles';
import SectionLabel from '../SectionLabel';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Typography from '@mui/material/Typography';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import Tooltip from '@mui/material/Tooltip';
import Moment from 'react-moment';
import MatchReport from '../dialogs/MatchReport';

const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
    height: '100%',
    display: 'flex',
    flexDirection: 'column',
  },
  content: {
    flex: 1,
    overflowY: 'auto',
    maxHeight: 480,
    padding: theme.spacing(0, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  row: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.6, 1),
    borderRadius: 6,
    '&:hover': {
      backgroundColor: theme.palette.action.hover,
    },
  },
  yearChip: {
    fontSize: '0.6rem',
    height: 18,
    fontWeight: 700,
    flexShrink: 0,
  },
  matchText: {
    fontSize: '0.8rem',
    fontWeight: 500,
    flex: 1,
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
  },
}));

export default function HappenedMatches({ matches, title }) {
  const classes = useStyles();
  const today = new Date();
  const [selectedMatch, setSelectedMatch] = useState(null);

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={
          <Chip
            label={<Moment format="D MMM">{today}</Moment>}
            size="small"
            style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }}
          />
        }
        title={title}
        subheader="Cagliari Calcio"
      />
      <CardContent className={classes.content}>
        <SectionLabel>Partite</SectionLabel>
        {matches.map((row, i) => (
          <React.Fragment key={row.ID_P}>
            {i > 0 && <Divider style={{ margin: '2px 0' }} />}
            <div className={classes.row} style={{ cursor: 'pointer' }} onClick={() => { trackCardClick('accadde_oggi_partite'); setSelectedMatch({ ...row, played: 'Y', title: `${row.home} ${row.gh} - ${row.ga} ${row.away}` }); }}>
              <Chip
                label={<Moment locale='it' format="Y">{row.date}</Moment>}
                size="small"
                color="primary"
                className={classes.yearChip}
              />
              {row.league && (
                <Tooltip title={{ A: 'Serie A', B: 'Serie B', C1: 'Serie C1', '1RS': 'Prima divisione storica' }[row.league] ?? `Serie ${row.league}`} arrow>
                  <Chip
                    label={row.league}
                    size="small"
                    className={classes.yearChip}
                    style={{ backgroundColor: '#F0C040', color: '#082D68' }}
                  />
                </Tooltip>
              )}
              <Typography className={classes.matchText}>
                {row.home} <strong>{row.gh}</strong> — <strong>{row.ga}</strong> {row.away}
              </Typography>
              {(() => {
                const isCagliariHome = row.home === 'Cagliari';
                const cag = isCagliariHome ? parseInt(row.gh) : parseInt(row.ga);
                const opp = isCagliariHome ? parseInt(row.ga) : parseInt(row.gh);
                const { label, color } = cag > opp
                  ? { label: 'V', color: '#4caf50' }
                  : cag === opp
                  ? { label: 'P', color: '#9e9e9e' }
                  : { label: 'S', color: '#CA2331' };
                const tooltip = label === 'V' ? 'Vittoria' : label === 'P' ? 'Pareggio' : 'Sconfitta';
                return (
                  <Tooltip title={tooltip} arrow>
                    <Chip label={label} size="small" style={{ fontSize: '0.58rem', height: 18, fontWeight: 800, backgroundColor: color, color: '#fff', flexShrink: 0 }} />
                  </Tooltip>
                );
              })()}
            </div>
          </React.Fragment>
        ))}
      </CardContent>
      {selectedMatch && (
        <MatchReport
          open={Boolean(selectedMatch)}
          handleClose={() => setSelectedMatch(null)}
          title={selectedMatch.title}
          report={selectedMatch.report}
          played={selectedMatch.played}
          opponentTeamId={0}
          match={selectedMatch}
        />
      )}
    </Card>
  );
}
