import React, { useEffect } from 'react';
import SEO from '../components/SEO';
import Sidebar from './../components/Sidebar.js'
import Toolbar from '@mui/material/Toolbar';
import Paper from '@mui/material/Toolbar';
import AppBar from '@mui/material/AppBar';
import Footer from '../components/Footer';

const addScript = ({ src, id, onLoad }) => {
    const existing = document.getElementById(id);
    if (existing) {
        return existing;
    } else {
        const script = document.createElement("script");
        script.src = src;
        script.id = id;
        script.async = true;
        script.onload = () => {
            if (onLoad) {
                onLoad();
            }
        };
        document.getElementById("container").appendChild(script);
        return script;
    }
};

const removeScript = ({ id }) => {
    const script = document.getElementById(id);
    if (script) {
        document.body.removeChild(script);
    }
};

export default function Privacy() {
    useEffect(() => {
        const script = addScript({
            src: `https://cdn-cookieyes.com/client_data/386bc29ce3000fa59335c4a83482f224/script.js`,
            id: "privacy-script",
            onLoad: () => {
                console.log("Script loaded!");
            },
        });
        return () => removeScript({ id: script.id });
    }, []);

    return (
        <div>
            <SEO
              title="Privacy Policy"
              description="Informativa sulla privacy di ArchivioRossoBlu."
              path="/cagliari-calcio/privacy"
            />
            <AppBar position="static">
                <Toolbar>
                    <Sidebar />
                </Toolbar>
            </AppBar>
            <Paper>
                <div id="container"></div>
            </Paper>
            <Footer></Footer>
        </div>
    )
}

