import React, { useState } from 'react';
import Button from '@mui/material/Button';
import CircularProgress from '@mui/material/CircularProgress';
import IosShareIcon from '@mui/icons-material/IosShare';
import DownloadIcon from '@mui/icons-material/Download';

const W = 1080;
const H = 1080;
const RED   = '#CA2331';
const BLUE  = '#082D68';
const GOLD  = '#F0C040';
const WHITE = '#FFFFFF';
const GREY  = '#F5F7FA';

const COUNTRY_ISO = {
  'Italia': 'it', 'Francia': 'fr', 'Brasile': 'br', 'Argentina': 'ar',
  'Spagna': 'es', 'Grecia': 'gr', 'Svizzera': 'ch', 'Belgio': 'be',
  'Danimarca': 'dk', 'Inghilterra': 'gb', 'Perù': 'pe', 'Portogallo': 'pt',
  'Olanda': 'nl', 'Romania': 'ro', 'Bulgaria': 'bg', 'Estonia': 'ee',
  'Polonia': 'pl', 'Slovacchia': 'sk', 'Svezia': 'se', 'Croazia': 'hr',
  'Ungheria': 'hu', 'Slovenia': 'si', 'Serbia': 'rs', 'Moldavia': 'md',
  'Rep. Ceca': 'cz', 'Macedonia': 'mk', 'Bielorussia': 'by', 'Angola': 'ao',
  'Cameroun': 'cm', 'Ghana': 'gh', 'Marocco': 'ma', 'Senegal': 'sn',
  'Sierra Leone': 'sl', 'Sud Africa': 'za', 'Zambia': 'zm', 'Rep. Congo': 'cg',
  'Colombia': 'co', 'Cile': 'cl', 'Honduras': 'hn', 'Panama': 'pa',
  'Uruguay': 'uy', 'Venezuela': 've', 'Uzbekistan': 'uz', 'Corea del Nord': 'kp',
  'Germania': 'de', 'Austria': 'at', 'Turchia': 'tr', 'Russia': 'ru',
  'Galles': 'gb-wls', 'Scozia': 'gb-sct', 'Irlanda': 'ie', 'Ucraina': 'ua',
};

function loadImg(url) {
  return new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    const timer = setTimeout(() => resolve(null), 6000);
    img.onload = () => { clearTimeout(timer); resolve(img); };
    img.onerror = () => { clearTimeout(timer); resolve(null); };
    img.src = url;
  });
}

function drawRoundedRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

function shadowCard(ctx, x, y, w, h, r = 14) {
  ctx.fillStyle = WHITE;
  ctx.shadowColor = 'rgba(0,0,0,0.08)';
  ctx.shadowBlur = 18;
  ctx.shadowOffsetY = 4;
  drawRoundedRect(ctx, x, y, w, h, r);
  ctx.fill();
  ctx.shadowColor = 'transparent';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetY = 0;
}

function drawChip(ctx, text, cx, cy, bg, fg = WHITE, fontSize = 20) {
  const PAD = 16;
  ctx.font = `bold ${fontSize}px sans-serif`;
  const tw = ctx.measureText(text).width;
  const cw = tw + PAD * 2;
  const ch = fontSize + 14;
  ctx.fillStyle = bg;
  drawRoundedRect(ctx, cx - cw / 2, cy - ch / 2, cw, ch, ch / 2);
  ctx.fill();
  ctx.fillStyle = fg;
  ctx.textAlign = 'center';
  ctx.fillText(text, cx, cy + fontSize * 0.35);
}

function computeStats(seasons) {
  const s = seasons || [];
  const totals = s.reduce((acc, r) => ({
    presenze: acc.presenze + Math.max(0, parseInt(r.appareances) || 0),
    gol:      acc.gol      + Math.max(0, parseInt(r.goal)        || 0),
  }), { presenze: 0, gol: 0 });
  const years = s.map(r => parseInt(String(r.year || '').slice(0, 4))).filter(n => n > 1900);
  const from  = years.length ? Math.min(...years) : null;
  const to    = years.length ? Math.max(...years) + 1 : null;
  const period = from && to ? `${from}–${to}` : '—';
  let best = null;
  s.forEach(r => {
    const a = parseInt(r.appareances);
    if (a > 0 && (!best || a > parseInt(best.appareances))) best = r;
  });
  return { presenze: totals.presenze, gol: totals.gol, stagioni: s.length, period, best };
}

async function generateCard(data, seasons) {
  const stats = computeStats(seasons);
  const iso   = COUNTRY_ISO[data.country];

  const [photoImg, flagImg] = await Promise.all([
    data.photo ? loadImg(`https://www.archiviorossoblu.it/images/giocatori/${data.photo}`) : Promise.resolve(null),
    iso        ? loadImg(`https://flagcdn.com/w40/${iso}.png`)                              : Promise.resolve(null),
  ]);

  const canvas = document.createElement('canvas');
  canvas.width  = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');

  // ── Background ──
  ctx.fillStyle = GREY;
  ctx.fillRect(0, 0, W, H);

  // ── Header ──
  ctx.fillStyle = RED;
  ctx.fillRect(0, 0, W, 7);
  const hGrad = ctx.createLinearGradient(0, 7, 0, 150);
  hGrad.addColorStop(0, BLUE);
  hGrad.addColorStop(1, '#0d3d8f');
  ctx.fillStyle = hGrad;
  ctx.fillRect(0, 7, W, 143);

  ctx.font = 'bold 52px sans-serif';
  ctx.fillStyle = WHITE;
  ctx.textAlign = 'center';
  ctx.fillText('ArchivioRossoBlu', W / 2, 80);
  drawChip(ctx, 'Giocatore', W / 2, 118, GOLD, BLUE, 20);

  // ── Player card ──
  const CX = 40, CY = 168, CW = W - 80, CH = 300;
  shadowCard(ctx, CX, CY, CW, CH);
  ctx.fillStyle = RED;
  drawRoundedRect(ctx, CX, CY, CW, 7, 4);
  ctx.fill();

  // Avatar
  const AV_R  = 96;
  const AV_CX = CX + AV_R + 36;
  const AV_CY = CY + CH / 2 + 14;

  ctx.save();
  ctx.beginPath();
  ctx.arc(AV_CX, AV_CY, AV_R, 0, Math.PI * 2);
  ctx.clip();
  if (photoImg) {
    ctx.drawImage(photoImg, AV_CX - AV_R, AV_CY - AV_R, AV_R * 2, AV_R * 2);
  } else {
    ctx.fillStyle = BLUE;
    ctx.fill();
    ctx.restore();
    ctx.save();
    ctx.font = `bold ${Math.round(AV_R * 0.68)}px sans-serif`;
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    ctx.textAlign = 'center';
    const ini = `${(data.name || '').charAt(0)}${(data.surname || '').charAt(0)}`.toUpperCase();
    ctx.fillText(ini, AV_CX, AV_CY + AV_R * 0.26);
  }
  ctx.restore();

  ctx.strokeStyle = GOLD;
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.arc(AV_CX, AV_CY, AV_R, 0, Math.PI * 2);
  ctx.stroke();

  // ── Right column — fixed Y positions relative to card top (CY) ──
  const TX    = AV_CX + AV_R + 44;
  const maxNW = CX + CW - TX - 32;

  // Name
  let dispName = `${data.name || ''} ${data.surname || ''}`.trim();
  ctx.font = 'bold 52px sans-serif';
  while (ctx.measureText(dispName).width > maxNW && dispName.length > 1)
    dispName = dispName.slice(0, -1);
  if (dispName !== `${data.name || ''} ${data.surname || ''}`.trim()) dispName += '…';
  ctx.fillStyle = BLUE;
  ctx.textAlign = 'left';
  ctx.fillText(dispName, TX, CY + 76);

  // Role
  if (data.role) {
    ctx.font = '28px sans-serif';
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillText(data.role, TX, CY + 116);
  }

  // Flag + country
  if (flagImg) {
    const FH = 26, FW = Math.round(FH * 1.5);
    ctx.save();
    drawRoundedRect(ctx, TX, CY + 132, FW, FH, 3);
    ctx.clip();
    ctx.drawImage(flagImg, TX, CY + 132, FW, FH);
    ctx.restore();
    if (data.country) {
      ctx.font = '26px sans-serif';
      ctx.fillStyle = 'rgba(0,0,0,0.45)';
      ctx.textAlign = 'left';
      ctx.fillText(data.country, TX + FW + 10, CY + 132 + FH * 0.78);
    }
  }

  // Date, birthplace, height/weight — stacked below with 28px line spacing
  let extraY = CY + 200;
  ctx.font = '24px sans-serif';
  ctx.fillStyle = 'rgba(0,0,0,0.45)';
  ctx.textAlign = 'left';

  if (data.date && data.date !== '0000-00-00') {
    const [yr, mo, dy] = data.date.split('-');
    const months = ['gen','feb','mar','apr','mag','giu','lug','ago','set','ott','nov','dic'];
    ctx.fillText(`${parseInt(dy)} ${months[parseInt(mo) - 1]} ${yr}`, TX, extraY);
    extraY += 28;
  }

  if (data.birthplace) {
    let loc = data.birthplace;
    while (ctx.measureText(loc).width > maxNW && loc.length > 1)
      loc = loc.slice(0, -1);
    if (loc !== data.birthplace) loc += '…';
    ctx.fillText(loc, TX, extraY);
    extraY += 28;
  }

  const hw = [
    parseInt(data.height) > 0 ? `${data.height} cm` : null,
    parseInt(data.weight) > 0 ? `${data.weight} kg` : null,
  ].filter(Boolean).join('  ·  ');
  if (hw) ctx.fillText(hw, TX, extraY);

  // ── Stat boxes 2×2 ──
  const SY    = CY + CH + 24;
  const GAP   = 16;
  const SW    = (CW - GAP) / 2;
  const SH    = 128;
  const STATS = [
    { label: 'Presenze', value: stats.presenze, color: GOLD },
    { label: 'Gol',      value: stats.gol,       color: '#f87171' },
    { label: 'Stagioni', value: stats.stagioni,  color: BLUE },
    { label: 'Periodo',  value: stats.period,    color: BLUE },
  ];

  STATS.forEach((item, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const sx  = CX + col * (SW + GAP);
    const sy  = SY + row * (SH + GAP);
    shadowCard(ctx, sx, sy, SW, SH, 12);
    ctx.font = '22px sans-serif';
    ctx.fillStyle = 'rgba(0,0,0,0.45)';
    ctx.textAlign = 'center';
    ctx.fillText(item.label, sx + SW / 2, sy + 44);
    ctx.font = `bold 50px sans-serif`;
    ctx.fillStyle = item.color;
    ctx.textAlign = 'center';
    ctx.fillText(String(item.value), sx + SW / 2, sy + 102);
  });

  // ── Best season ──
  if (stats.best) {
    const BY  = SY + 2 * (SH + GAP);
    const BH  = 76;
    shadowCard(ctx, CX, BY, CW, BH, 12);
    const bsGol  = parseInt(stats.best.goal);
    const bsText = `Miglior stagione: ${stats.best.year}  ·  ${stats.best.appareances} presenze${bsGol > 0 ? `  ·  ${bsGol} gol` : ''}`;
    ctx.font = '26px sans-serif';
    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    ctx.textAlign = 'center';
    ctx.fillText(bsText, W / 2, BY + 46);
  }

  // ── Footer ──
  const FY = H - 80;
  ctx.fillStyle = BLUE;
  ctx.fillRect(0, FY, W, 80);
  ctx.fillStyle = RED;
  ctx.fillRect(0, FY, W, 5);
  ctx.font = 'bold 28px sans-serif';
  ctx.fillStyle = WHITE;
  ctx.textAlign = 'center';
  ctx.fillText('archiviorossoblu.it', W / 2, FY + 50);

  return canvas;
}

const isMobile = typeof navigator !== 'undefined' && /Mobi|Android|iPhone|iPad/i.test(navigator.userAgent);

export default function PlayerShareCard({ data, seasons }) {
  const [loading, setLoading] = useState(false);

  const handleClick = async () => {
    setLoading(true);
    try {
      const canvas = await generateCard(data, seasons);
      canvas.toBlob(async (blob) => {
        const fileName = `${data.name || ''}-${data.surname || ''}-arb.png`
          .toLowerCase().replace(/\s+/g, '-');
        if (isMobile && navigator.canShare) {
          const file = new File([blob], fileName, { type: 'image/png' });
          if (navigator.canShare({ files: [file] })) {
            await navigator.share({ files: [file], title: `${data.name} ${data.surname} – ArchivioRossoBlu` });
            return;
          }
        }
        const url = URL.createObjectURL(blob);
        const a   = document.createElement('a');
        a.href     = url;
        a.download = fileName;
        a.click();
        URL.revokeObjectURL(url);
      }, 'image/png');
    } catch (e) {
      if (e?.name !== 'AbortError' && e?.message !== 'Share canceled') {
        console.error('PlayerShareCard error:', e);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <Button
      variant="outlined"
      size="small"
      startIcon={loading
        ? <CircularProgress size={14} color="inherit" />
        : isMobile ? <IosShareIcon fontSize="small" /> : <DownloadIcon fontSize="small" />
      }
      onClick={handleClick}
      disabled={loading}
      style={{ borderColor: '#082D68', color: '#082D68', fontWeight: 600, fontSize: '0.78rem' }}
    >
      {loading ? 'Generando…' : 'Condividi scheda'}
    </Button>
  );
}
