import React, { useState } from 'react';
import { trackCardClick } from '../../utils/analytics';
import { makeStyles } from '@mui/styles';
import SectionLabel from '../SectionLabel';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardMedia from '@mui/material/CardMedia';
import CardContent from '@mui/material/CardContent';
import CardActions from '@mui/material/CardActions';
import Typography from '@mui/material/Typography';
import Avatar from '@mui/material/Avatar';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import QueryStatsIcon from '@mui/icons-material/QueryStats';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import SportsSoccerIcon from '@mui/icons-material/SportsSoccer';
import EventIcon from '@mui/icons-material/Event';
import CakeIcon from '@mui/icons-material/Cake';
import IconButton from '@mui/material/IconButton';
import Moment from 'react-moment';
import 'moment/locale/it';
import { allCountries } from '../../utils/generals'
import StatsList from '../dialogs/StatsList'
import PlayerReport from '../dialogs/PlayerReport'
import Flag from '../Flag'
import * as ARBApi from '../../utils/ARBApi'


const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
    height: '100%',
    display: 'flex',
    flexDirection: 'column',
  },
  media: {
    height: 0,
    paddingTop: '56.25%',
  },
  content: {
    flex: 1,
    padding: theme.spacing(0, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  row: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.6, 1),
    borderRadius: 6,
    '&:hover': {
      backgroundColor: theme.palette.action.hover,
    },
  },
  infoAvatar: {
    width: 22,
    height: 22,
    fontSize: '0.55rem',
    fontWeight: 700,
    backgroundColor: '#082D68',
    color: '#fff',
    flexShrink: 0,
  },
  infoText: {
    fontSize: '0.8rem',
    fontWeight: 500,
    flex: 1,
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
  },
  actions: {
    padding: theme.spacing(1, 2, 1.5),
    justifyContent: 'flex-end',
  },
  statChip: {
    fontWeight: 700,
    fontSize: '0.82rem',
  },
}));

export default function Players({ players, type }) {
  const classes = useStyles();
  const player = players[0];
  const country = allCountries.filter(c => c.description === player.country);
  let imagePlayer = `https://www.archiviorossoblu.it/images/giocatori/${player.photo}`;
  if (type === 'Allenatori') {
    imagePlayer = `https://www.archiviorossoblu.it/images/allenatori/${player.photo}`;
    player.role = 'Allenatore';
  }
  const name = `${player.name} ${player.surname}`;
  const chipLabel = `TOP ${type}`;
  const isGoals = type === 'Gol' || type === 'Gol Subiti';

  const [openStatList, setOpenStatList] = useState(false);
  const handleClickOpen = () => setOpenStatList(true);
  const handleClose = () => setOpenStatList(false);

  const [playerReport, setPlayerReport] = useState(null);
  const openPlayer = () => {
    trackCardClick(`player_top_${type.toLowerCase().replace(/\s+/g, '_')}`);
    ARBApi.getAllByID('playerDetails', player.id).then((report) => {
      setPlayerReport(report?.data ? report : { data: player, seasons: [] });
    });
  };

  return (
    <Card className={classes.root}>
      <CardHeader
        action={
          <div style={{ display: 'flex' }}>
            {type !== 'Allenatori' && (
              <IconButton size="small" onClick={openPlayer}>
                <MoreVertIcon fontSize="small" />
              </IconButton>
            )}
            <IconButton aria-label="classifica completa" onClick={handleClickOpen}>
              <QueryStatsIcon />
            </IconButton>
          </div>
        }
        avatar={
          <Chip label={chipLabel} size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        }
        title={
          type === 'Allenatori' ? name : (
            <Typography
              style={{ fontWeight: 600, fontSize: '1rem', cursor: 'pointer', display: 'inline' }}
              onClick={openPlayer}
            >
              {name}
            </Typography>
          )
        }
        subheader={player.role}
      />
      <CardMedia className={classes.media} image={imagePlayer} title={name} />
      <CardContent className={classes.content}>
        <SectionLabel>Info</SectionLabel>
        <div className={classes.row}>
          {country[0] && <Flag filename={country[0].flag} country={player.country} />}
          <Typography className={classes.infoText}>{player.birthplace}</Typography>
        </div>
        {player.date !== '0000-00-00' && (
          <>
            <Divider style={{ margin: '2px 0' }} />
            <div className={classes.row}>
              <Avatar className={classes.infoAvatar}><CakeIcon style={{ fontSize: 14 }} /></Avatar>
              <Typography className={classes.infoText}>
                <Moment locale='it' format="LL">{player.date}</Moment>
              </Typography>
            </div>
          </>
        )}
      </CardContent>
      {player.value !== -1 && (
        <CardActions className={classes.actions}>
          <Chip
            className={classes.statChip}
            icon={isGoals ? <SportsSoccerIcon /> : <EventIcon />}
            label={`${player.value} ${isGoals ? 'gol' : 'presenze'}`}
            color="primary"
          />
        </CardActions>
      )}
      {playerReport && (
        <PlayerReport
          open={!!playerReport}
          handleClose={() => setPlayerReport(null)}
          playerReport={playerReport}
          playerId={player.id}
        />
      )}
      <StatsList
        open={openStatList}
        onClickClose={handleClose}
        title={name}
        type={type}
        players={players}
      />
    </Card>
  );
}
