import React, { useState } from 'react';
import { trackCardClick, trackNextPlayer } from '../../utils/analytics';
import CircularProgress from '@mui/material/CircularProgress';
import { makeStyles } from '@mui/styles';
import SectionLabel from '../SectionLabel';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import CardActions from '@mui/material/CardActions';
import Typography from '@mui/material/Typography';
import Avatar from '@mui/material/Avatar';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import IconButton from '@mui/material/IconButton';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import RefreshIcon from '@mui/icons-material/Refresh';
import Moment from 'react-moment';
import 'moment/locale/it';
import { allCountries, allRoles } from '../../utils/generals'
import CakeIcon from '@mui/icons-material/Cake';
import Flag from '../Flag'
import PlayerReport from '../dialogs/PlayerReport'
import * as ARBApi from '../../utils/ARBApi'


const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
    height: '100%',
    display: 'flex',
    flexDirection: 'column',
  },
  mediaWrapper: {
    height: 220,
    backgroundColor: '#f0f0f0',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'hidden',
  },
  mediaImg: {
    height: '100%',
    width: 'auto',
    maxWidth: '100%',
    objectFit: 'contain',
    objectPosition: 'top',
  },
  content: {
    flex: 1,
    padding: theme.spacing(0, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  row: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.6, 1),
    borderRadius: 6,
    '&:hover': {
      backgroundColor: theme.palette.action.hover,
    },
  },
  infoAvatar: {
    width: 22,
    height: 22,
    fontSize: '0.55rem',
    fontWeight: 700,
    backgroundColor: '#082D68',
    color: '#fff',
    flexShrink: 0,
  },
  infoText: {
    fontSize: '0.8rem',
    fontWeight: 500,
    flex: 1,
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
  },
  actions: {
    padding: theme.spacing(1, 2, 1.5),
    justifyContent: 'space-between',
  },
}));

export default function RandomPlayer({ player: initialPlayer, seasons: initialSeasons = [], title }) {
  const classes = useStyles();
  const [player, setPlayer] = useState(initialPlayer);
  const [seasons, setSeasons] = useState(initialSeasons);
  const [playerReport, setPlayerReport] = useState(null);
  const [loadingNext, setLoadingNext] = useState(false);

  const openPlayer = () => {
    trackCardClick('random_player');
    ARBApi.getAllByID('playerDetails', player.ID).then((report) => {
      const fallback = { data: { ...player, date: player.birth }, seasons: [] };
      setPlayerReport(report?.data ? report : fallback);
    });
  };

  const nextPlayer = () => {
    trackNextPlayer();
    setLoadingNext(true);
    ARBApi.getFresh('randomPlayer').then((data) => {
      const next = data?.player?.[0];
      if (next) setPlayer(next);
      setSeasons(data?.seasons ?? []);
    }).finally(() => setLoadingNext(false));
  };

  const country = allCountries.filter(c => c.description === player.country);
  const imagePlayer = `https://www.archiviorossoblu.it/images/giocatori/${player.photo}`;
  const name = `${player.name} ${player.surname}`;
  const roleData = allRoles.filter(r => r.description === player.role);
  const roleLabel = roleData.length > 0 ? roleData[0].role : player.role;

  const totalApp     = seasons.reduce((s, r) => s + Math.max(0, Number(r.appareances)), 0);
  const totalGol     = seasons.reduce((s, r) => s + Math.max(0, Number(r.goal)), 0);
  const totalYellow  = seasons.reduce((s, r) => s + Math.max(0, Number(r.yellowcard)), 0);
  const totalRed     = seasons.reduce((s, r) => s + Math.max(0, Number(r.redcard)), 0);
  const totalSeas    = seasons.length;
  const firstSeason  = totalSeas > 0
    ? [...seasons].sort((a, b) => a.year.slice(0, 4).localeCompare(b.year.slice(0, 4)))[0]
    : null;

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={
          <Chip label={title} size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        }
        action={
          <IconButton aria-label="dettagli" onClick={openPlayer}>
            <MoreVertIcon />
          </IconButton>
        }
        title={
          <Typography
            style={{ fontWeight: 600, fontSize: '1rem', cursor: 'pointer', display: 'inline' }}
            onClick={openPlayer}
          >
            {name}
          </Typography>
        }
        subheader={player.role}
      />
      <div className={classes.mediaWrapper}>
        <img src={imagePlayer} alt={name} className={classes.mediaImg} />
      </div>
      <CardContent className={classes.content}>
        <SectionLabel>Info</SectionLabel>
        <div className={classes.row}>
          {country[0] && <Flag filename={country[0].flag} country={player.country} />}
          <Typography className={classes.infoText}>{player.birthplace}</Typography>
        </div>
        {player.birth && player.birth !== '0000-00-00' && (
          <>
            <Divider style={{ margin: '2px 0' }} />
            <div className={classes.row}>
              <Avatar className={classes.infoAvatar}><CakeIcon style={{ fontSize: 14 }} /></Avatar>
              <Typography className={classes.infoText}>
                <Moment locale='it' format="LL">{player.birth}</Moment>
              </Typography>
            </div>
          </>
        )}
        {totalSeas > 0 && (
          <>
            <Divider style={{ margin: '4px 0' }} />
            <SectionLabel>Carriera</SectionLabel>
            <div style={{ display: 'flex', justifyContent: 'space-around', padding: '4px 0 2px' }}>
              <div style={{ textAlign: 'center' }}>
                <Typography style={{ fontWeight: 700, fontSize: '1.1rem', color: '#082D68' }}>{totalSeas}</Typography>
                <Typography style={{ fontSize: '0.65rem', color: 'rgba(0,0,0,0.5)' }}>Stagioni</Typography>
              </div>
              <div style={{ textAlign: 'center' }}>
                <Typography style={{ fontWeight: 700, fontSize: '1.1rem', color: '#082D68' }}>{totalApp}</Typography>
                <Typography style={{ fontSize: '0.65rem', color: 'rgba(0,0,0,0.5)' }}>Presenze</Typography>
              </div>
              <div style={{ textAlign: 'center' }}>
                <Typography style={{ fontWeight: 700, fontSize: '1.1rem', color: '#CA2331' }}>{totalGol}</Typography>
                <Typography style={{ fontSize: '0.65rem', color: 'rgba(0,0,0,0.5)' }}>{player.role === 'Portiere' ? 'Gol Subiti' : 'Gol'}</Typography>
              </div>
              {totalYellow > 0 && (
                <div style={{ textAlign: 'center' }}>
                  <Typography style={{ fontWeight: 700, fontSize: '1.1rem', color: '#f5a623' }}>{totalYellow}</Typography>
                  <Typography style={{ fontSize: '0.65rem', color: 'rgba(0,0,0,0.5)' }}>Amm.</Typography>
                </div>
              )}
              {totalRed > 0 && (
                <div style={{ textAlign: 'center' }}>
                  <Typography style={{ fontWeight: 700, fontSize: '1.1rem', color: '#CA2331' }}>{totalRed}</Typography>
                  <Typography style={{ fontSize: '0.65rem', color: 'rgba(0,0,0,0.5)' }}>Esp.</Typography>
                </div>
              )}
            </div>
            {firstSeason && (
              <div style={{ display: 'flex', justifyContent: 'center', paddingTop: 6 }}>
                <Chip
                  label={`Prima stagione: ${firstSeason.year} · Serie ${firstSeason.league}`}
                  size="small"
                  style={{ fontSize: '0.62rem', fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }}
                />
              </div>
            )}
          </>
        )}
      </CardContent>
      <CardActions className={classes.actions}>
        <Chip
          label={roleLabel}
          color="primary"
          size="small"
          style={{ fontSize: '0.6rem', height: 18, fontWeight: 700 }}
        />
        <Chip
          icon={loadingNext ? <CircularProgress size={10} style={{ color: '#082D68' }} /> : <RefreshIcon style={{ fontSize: 14 }} />}
          label="Prossimo"
          size="small"
          onClick={nextPlayer}
          disabled={loadingNext}
          style={{ fontSize: '0.7rem', height: 22, fontWeight: 700, cursor: 'pointer', backgroundColor: '#F0C040', color: '#082D68' }}
        />
      </CardActions>
      {playerReport && (
        <PlayerReport
          open={!!playerReport}
          handleClose={() => setPlayerReport(null)}
          playerReport={playerReport}
          playerId={player.ID}
        />
      )}
    </Card>
  );
}
